	db.Create(&project)

	// Set retries to MaxConstraintGateRetries-1 so the next failure exhausts.
	// Also set next_check in the past so the gate actually evaluates.
	pastCheck := time.Now().Add(-1 * time.Minute).Format(time.RFC3339)
